<?phpnamespace hema;use app\common\model\Order as OrderModel;use app\common\model\Setting;use app\common\model\OrderDelivery as OrderDeliveryModel;use hema\alipay\Driver as Alipay;use think\facade\Cache;use think\facade\Db;class Order{    private $model;    /**     * 构造函数     */    public function __construct()    {        $this->model = new OrderModel;    }    /**     * 监听事件     */    public function listen()    {        //判断是否获取到”task_space_order“        if (!Cache::get('order_event')) {            $config = Setting::getItem('trade');            $after_pay = Setting::getItem('order')['after_pay'];            //判断是否关闭线下支付            if($after_pay==1){                // 未支付订单自动关闭                $this->close($config['close_time']);            }            // 待配送订单自动配送完成(堂食，自取)            $this->delivery($config['delivery_time']);            // 待配送订单自动配送完成(外卖)            $this->waimai($config['delivery_time']);            //配送完成订单用户自动确认收货            $this->receive($config['receive_time']);            //收货订单自动评价            $this->cmt($config['cmt_time']);            // 退款订单自动退款            $this->refund($config['refund_time']);            //自动处理支付宝退款中的订单            $this->alipayRefund();            Cache::set('order_event', time(), $config['time']*60);//有效期N分钟        }        return true;    }        /**     * 未支付订单自动关闭     */    private function close($close_time)    {        // 小于1说明未开启该自动操作        if ($close_time < 1) {            return false;        }        // 截止时间        $deadlineTime = time() - ((int)$close_time * 60);//分钟        // 条件        $filter = [            'pay_status' => 10,//未支付            'order_status' => 10,//进行中        ];        // 查询截止时间未支付的订单        $orderIds = $this->model->where($filter)->where('create_time','<',$deadlineTime)->column('order_id');        // 直接更新        if (sizeof($orderIds) > 0) {            $this->model->where('order_id','in',$orderIds)->save(['order_status' => 20]);        }        return true;    }    /**     * 配送中订单自动配送完成（外卖）     */    private function waimai($delivery_time)    {        return false;        // 订单配送n小时后自动完成配送        if ($delivery_time < 1) {            return false;        }        // 截止时间        $deadlineTime = time() - ((int)$delivery_time * 60);        //条件        $filter = [            'order_mode' => 20,            'shop_status' => 20,            'delivery_status' => 20,            'order_status' => 10,        ];        // 查询截止时间未完成配送的订单        $orderIds = $this->model->where($filter)->where('pay_status',20)->where('delivery_time','<',$deadlineTime)->column('order_id');        // 直接更新        if (sizeof($orderIds) > 0) {            //循环发送配送完成提醒订阅消息            /*for($n=0;$n<sizeof($orderIds);$n++){                $this->model->sendMessage('delivery',$orderIds[$n]);            }*/            $deliveryModel = new OrderDeliveryModel;            $deliveryModel->where('order_id','in',$orderIds)->save([                'delivery_status' => 50,                'delivery_time' => time()            ]);            return $this->model->where('order_id','in',$orderIds)->save([                'delivery_status' => 30,                'delivery_time' => time()            ]);        }        return true;    }        /**     * 已接订单自动完成配送（堂食、自取）     */    private function delivery($delivery_time)    {        // 订单配送n小时后自动完成配送        if ($delivery_time < 1) {            return false;        }        // 截止时间        $deadlineTime = time() - ((int)$delivery_time * 60);        //堂食扫码        $filter = [            'order_mode' => 10,            'shop_status' => 20, //商家已接单            'delivery_status' => 10,            'order_status' => 10,        ];        // 查询截止时间未完成配送的订单        $orderIds = $this->model->where($filter)            ->where('order_mode','<>',20)            ->where('shop_time','<',$deadlineTime)            ->column('order_id');        // 直接更新        if (sizeof($orderIds) > 0) {            foreach ($orderIds as $item){                $order = OrderModel::get($item);                if($order['table_id'] == 0){                    $this->model->sendMessage('take',$item);                }            }            return $this->model->where('order_id','in',$orderIds)->save([                'delivery_status' => 30,                'delivery_time' => time()            ]);        }        return true;    }    /**     * 已配送订单自动确认收货     */    private function receive($receive_time)    {        if ($receive_time < 1) {            return false;        }        // 截止时间        $deadlineTime = time() - ((int)$receive_time * 60); //分钟        //条件        $filter = [            'pay_status' => 20, //已付款            'delivery_status' => 30,            'receipt_status' => 10,            'order_status' => 10,        ];        // 查询截止时间未支付的订单        $orderIds = $this->model->where($filter)->where('delivery_time','<',$deadlineTime)->column('order_id');        // 直接更新        if (sizeof($orderIds) > 0) {            // 开启事务            Db::startTrans();            try {                $this->model->where('order_id','in',$orderIds)->save([                    'receipt_status' => 20,                    'receipt_time' => time(),                    'order_status' => 30                ]);                Db::commit();                return true;            } catch (\Exception $e) {                Db::rollback();            }          }        return true;    }        /**     * 已收货订单自动评价     */    private function cmt($cmt_time)    {        if ($cmt_time < 1) {            return false;        }        // 截止时间        $deadlineTime = time() - ((int)$cmt_time * 60); //分钟        //条件        $filter = [            'is_cmt' => 0,            'receipt_status' => 20,            'order_status' => 30,        ];        // 查询截止时间未支付的订单        $orderIds = $this->model->where($filter)->where('receipt_time','<',$deadlineTime)->column('order_id');        foreach ($orderIds as $item){            $order = OrderModel::get($item,['comment']);            $order->comment()->save([                'content' => '自动评价',                'user_id' => $order['user_id'],            ]);            $order->save(['is_cmt' => 1]);        }        return true;    }    /**     * 退款订单自动完成退款     */    private function refund($refund_time)    {        if ($refund_time < 1) {            return false;        }        // 截止时间        $deadlineTime = time() - ((int)$refund_time * 60); //分钟        //条件        $filter = [            'pay_status' => 20,            'receipt_status' => 10,            'refund_status' => 10,            'order_status' => 40,        ];        // 查询截止时间未支付的订单        $orderIds = $this->model->where($filter)->where('refund_time','<',$deadlineTime)->column('order_id');        foreach ($orderIds as $item){            if($order = OrderModel::get($item)){                $order->refund(1);//同意退款            }        }        return true;    }    /**     * 自动处理支付宝退款中的订单     */    private function alipayRefund()    {        // 条件        $filter = [            'pay_status' => 20,//已支付            'pay_mode' => 4,//支付宝付款            'order_status' => 40,//退款订单            'refund_status' => 30,//退款中        ];        // 查询截止时间未支付的订单        $orderIds = $this->model->where($filter)->column('order_id');        foreach ($orderIds as $item){            if($order = OrderModel::get($item,['goods'])){                $aliPay = new Alipay();                if($aliPay->tradeFastpayRefundQuery($order['transaction_id'])){                    $order->refundCallback();//退款成功回调                }            }        }        return true;    }}